#!/usr/bin/env bash
# Generate the right-to-left sibling of every shipped stylesheet with rtlcss —
# the same tool WordPress core and wp-scripts use — as assets/css/X-rtl.css.
# WordPress loads the sibling on RTL locales because each handle is registered
# with wp_style_add_data( $handle, 'rtl', 'replace' ).
#
# The generated files are COMMITTED (so a checkout works as a plugin directory
# and CI needs no node), and each carries a stamp with the SHA-1 of the source
# it was generated from; tests/Unit/RtlStylesheetsTest.php fails when a source
# changed without this script being re-run.
#
#   ./bin/build-rtl.sh                       # regenerate every assets/css/*.css
#   RTLCSS=/path/to/rtlcss ./bin/build-rtl.sh   # use a local binary
#
# Needs node; without RTLCSS set, npx fetches rtlcss on first use. Never edit a
# -rtl.css by hand.
set -euo pipefail
cd "$(dirname "$0")/.."

run_rtlcss() {
  if [ -n "${RTLCSS:-}" ]; then "$RTLCSS" "$1" "$2"; else npx --yes rtlcss@4.3.0 "$1" "$2"; fi
}

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
for src in assets/css/*.css; do
  case "$src" in *-rtl.css) continue;; esac
  out="${src%.css}-rtl.css"
  sum=$(shasum -a 1 "$src" | cut -d' ' -f1)
  run_rtlcss "$src" "$tmp"
  {
    printf '/* rtl: generated by bin/build-rtl.sh from %s (sha1 %s) - do not edit; re-run the script */\n' "$(basename "$src")" "$sum"
    cat "$tmp"
  } > "$out"
  echo "  $src -> $out"
done
